INSERT IGNORE INTO `group_sites` (`id`, `title`, `description`, `image_path`, `logo_path`, `status`, `invite_code`, `admin_user_id`, `created_at`, `updated_at`) VALUES
(1, 'علماء الفلك', 'علماء الفلك علماء الفلك', NULL, NULL, 'open', NULL, 1, '2026-10-03 14:11:47', '2026-10-03 14:11:47'),
(2, 'الاتحاد الدولي للحقوقين', 'نحن الحقوقين قررانا تأسيس الاتحاد العالمي للحقوقين كمؤسسة مستقلة بهدف حماية حقوق وكرامة الانسان وتاسس مبدأ سيادة العدالة والقانون وانطلاقا من ادراكنا بأن كل الموجودات التي على الأرض هي أمانة في عنق الانسان فان احد أهدافنا هو حمايتهم والتعايش معهم بشكل متلازم لكل انسان مهما كان دينة أو عرقة او لونة او لغتة و جنسة او توجهة السياسي او قنعاتة الفلسفية أو تبعتة الاجتماعية أوأصلة بصفتة فرد شريق من أفراد العائلة البشرية كل الحقوق والحريات بدءا من حق الحياة الى حق الحرية الى حق المساواة الى حق المحاكمة العادلة وحق الأمن الشخصي وحق الاعتقاد والتفكير والتعبير كيفما يشاء وحق التمالك ويجب ان توضع هذة الحريات والحقوق تحت ضمانة القانون وبشكل يليق بكرامة واعتبار الانسان', 'photos/2017/01/world_c7b91ae1676cf8c30fc29a5dff852f14.jpg', 'photos/2017/01/world_9f6495f6173ee1a751cb4c716dcb15c0.jpg', 'open', NULL, 2, '2026-10-03 14:11:47', '2026-10-03 14:11:47'),
(3, 'مسابقة حكماء العالم', 'قم بطرح موضوع او فيديو او صور لها قيمة في مختلف المجالات داخل جروب مسابقة حكماء العالم وادعو اصدقائك للمشاركة في  موضوعك و الاعجاب بة ا و التعليق علية اكثر الموضيع لها قيمة و لاقت اهتمام اكتر من الاعضاء سوف تربح احد الجوائز القيمة', NULL, 'photos/2017/01/world_95d874a1cab8e5db43b43c6141c1147a.jpg', 'open', NULL, 2, '2026-10-03 14:11:47', '2026-10-03 14:11:47'),
(4, 'Group قضايا إجتماعية', 'القضية الاجتماعية  لها مصطلحات عدة مثل :  المشاكل الاجتماعية ،الصراع الاجتماعي والمعاناة الاجتماعية . وتشير أيضا  القضية بأنها تؤثر على شريحة كبيرة من الأفراد داخل المجتمع .', 'photos/2017/03/world_ac84b340ee38ea7bc2c6dd55f2f38acb.jpg', 'photos/2017/03/world_cce701962a2c826a82c4c853e84f7382.jpg', 'open', NULL, 181, '2017-03-23 08:47:57', '2017-03-23 08:47:57'),
(5, 'القضية الفلسطينية تناديكم', 'القضية الاجتماعية لها مصطلحات عدة مثل : المشاكل الاجتماعية ،الصراع الاجتماعي والمعاناة الاجتماعية . وتشير أيضا القضية بأنها تؤثر على شريحة كبيرة من الأفراد داخل المجتمع .\\r\\n', NULL, 'photos/2024/04/world_94c98ec2d717fafa94b6fc638e525963.jpg', 'open', NULL, 181, '2017-03-28 12:34:52', '2017-03-28 12:34:52'),
