(14, 'سياسة', 'سياسة', NULL, NULL, 'open', NULL, 2533, '2017-05-15 18:58:37', '2017-05-15 18:58:37'),
(15, 'شاركنا خبرتك', 'مساحة لكل شخص لديه تجربة أو معلومة أو نصيحة يمكن أن تفيد غيره.\r\nهنا نتبادل الخبرات، ونتعلم من تجارب بعضنا، ونطرح الأسئلة ونشارك الحلول والأفكار المفيدة في الحياة والعمل والدراسة والمجتمع.\r\nلا يشترط أن تكون خبيرًا؛ أحيانًا تكون تجربة بسيطة مررت بها سببًا في مساعدة شخص آخر. 🤍\r\n\r\nشارك تجربتك… فقد تكون سببًا في فائدة لا تعرف أثرها.', NULL, NULL, 'open', NULL, 37, '2026-09-21 01:24:31', '2026-09-21 01:24:31'),
(16, 'learning', '📚📚Learning\n | تعلّم كل يوم شيئًا جديدًا\nصفحة للمعرفة والتعلّم واكتشاف كل ما هو مفيد وممتع.\nمعلومات، علوم، مهارات، أفكار، ثقافة، وتطوير للذات بأسلوب بسيط وسهل.\nلأن كل معلومة جديدة… خطوة نحو عقل أكثر وعيًا وحياة أفضل', NULL, NULL, 'open', NULL, 37, '2026-09-27 09:56:27', '2026-09-27 10:04:42'),
(17, 'من كل بستان زهرة', NULL, NULL, NULL, 'open', NULL, 37, '2026-09-27 09:59:27', '2026-09-27 09:59:27'),
(18, 'أسرار المطبخ', 'هنا كل طبخة لها سر، وكل وصفة لها حكاية ❤️\nوصفات شهية، أفكار سهلة، حيل وأسرار المطبخ، نصائح للتوفير والترتيب، وكل ما يجعل طبخك أسهل وألذ.\nتابعينا واكتشفي كل يوم سرًا جديدًا يجعل سفرتك أجمل! 😋✨', NULL, NULL, 'open', NULL, 37, '2026-09-27 10:03:12', '2026-09-27 10:03:12'),
